uh(a,b){return"\ud604\uc7ac \uac00\uc7a5 \ud070 \uac00\uc911 \uae30\uc5ec\ub294 "+a+"\uc5d0\uc11c \ub098\uc635\ub2c8\ub2e4\uff08\uc57d "+b+" \ud37c\uc13c\ud2b8\ud3ec\uc778\ud2b8\uff09."},
guj(){return'"\uba85\ud655\ud55c AI \ubb38\uccb4\uac00 \uac10\uc9c0\ub418\uc9c0 \uc54a\uc74c"\uc740 \ubb38\uccb4 \uc5d4\uc9c4\uc774 \uace0\uc815\ub41c \ubb38\uc7a5 \ud328\ud134\uc774\ub098 \uc804\ud658\uc5b4 \ud328\ud134\uc744 \ucc3e\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc758\ubbf8\uc77c \ubfd0\uc774\uba70, \ub2e4\ub978 \ubaa8\ub378\uc740 \uc5b8\uc5b4 \uaddc\uce59\uc131, \ubb38\uc7a5 \ubd84\ub958, \uc7ac\uc791\uc131 \uc2e0\ud638\ub97c \ud1b5\ud574 \uc5ec\uc804\ud788 \uc804\uccb4 \uc810\uc218\ub97c \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},
